#!/usr/bin/env node
const NINTH_ORIGINAL_URL=new URL("../../../../../service-protocol/verify-service-protocol.mjs",import.meta.url);
import {eighthLeaf} from '../eighth-reconciliation/verify-dependencies.mjs';
// Dependency-free, read-only final-dist checks. State fixtures are illustrative contracts, not live RPC implementations.
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
const here=path.dirname(fileURLToPath(NINTH_ORIGINAL_URL));
const arg=(k,d)=>{const i=process.argv.indexOf(k);return i<0?d:process.argv[i+1];};
const mode=arg('--mode','final'),dist=path.resolve(arg('--dist','dist'));assert.ok(['candidate','final'].includes(mode));
const read=n=>JSON.parse(fs.readFileSync(path.join(here,n),'utf8'));const sha=s=>crypto.createHash('sha256').update(s,'utf8').digest('hex');
const rt=fs.readFileSync(path.join(here,'records.json'),'utf8'),pkg=JSON.parse(rt),ap=read('append-manifest.json'),pm=read('paragraph-map.json'),vm=read('variant-map.json'),identity=read('identity-baseline.json');
const entries=new Map();for(const f of fs.readdirSync(path.join(dist,'data/chapters')).filter(x=>x.endsWith('.json')))for(const e of JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',f),'utf8')).entries||[]){assert.ok(!entries.has(e.id));entries.set(e.id,e);}
import {verifyWorkflowMigration,assertRelocatedDestination} from './verify-phase4-migration.mjs';
const migrationText=fs.readFileSync(path.join(here,'phase4-workflow-migration.json'),'utf8');assert.equal(sha(migrationText),'5735798a9f05d576ceac08faa9f6c0894046c05c14567e613ecf70ef8f063f97');const migration=JSON.parse(migrationText);
let migrationSummary;const checks=[];let stagedLeaves=0,stagedAppends=0;
const check=(name,fn)=>{try{checks.push({name,status:'passed',...fn()});}catch(e){checks.push({name,status:'failed',error:e.message});}};
const get=(e,p)=>p.reduce((v,k)=>v[k],e);const set=(e,p,v)=>{p.slice(0,-1).reduce((v,k)=>v[k],e)[p.at(-1)]=v;};
const target=key=>{const k=key.lastIndexOf('#'),e=entries.get(key.slice(0,k)),id=key.slice(k+1);assert.ok(e,`missing entry ${key}`);const x=e.items.find((x,i)=>(x.id||String(i))===id);assert.ok(x,`missing question ${key}`);return x;};
const semanticBlocks=s=>[...s.matchAll(/<(p|h[1-6]|li|pre|summary)\b[^>]*>([\s\S]*?)<\/\1>/g)];
const balanced=s=>{const stack=[],voids=new Set(['br','hr','img','input','meta','link','wbr']);for(const m of s.matchAll(/<(\/?)([A-Za-z][\w-]*)\b[^>]*>/g)){const t=m[2].toLowerCase();if(m[1])assert.equal(stack.pop(),t);else if(!voids.has(t)&&!m[0].endsWith('/>'))stack.push(t);}assert.deepEqual(stack,[]);};
check('three-exact-leaf-guards',()=>{if(mode==='final')migrationSummary=verifyWorkflowMigration(migration,{here,pkg,pm,target,semanticBlocks});assert.equal(pkg.records.length,3);assert.deepEqual(pkg.records.map(r=>({entryId:r.entryId,path:r.path})),identity.changedLeaves);for(const r of pkg.records){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.notEqual(r.before,r.after);const e=entries.get(r.entryId);assert.ok(e);const v=get(e,r.path),accepted=mode==='final'?eighthLeaf(r.entryId,r.path,r.entryId==='ai-agent-5'?migration.expectedFinalBody:r.after):r.after;if(v!==accepted){assert.equal(mode,'candidate',`final dist lacks ${r.entryId}/${r.path.join('/')}`);assert.equal(v,r.before,`stale before ${r.entryId}/${r.path.join('/')}`);set(e,r.path,r.after);stagedLeaves++;}}return {leaves:pkg.records.length,stagedInMemory:stagedLeaves,alreadyApplied:pkg.records.length-stagedLeaves,siteWrites:0};});
check('two-approved-authored-appends',()=>{assert.equal(ap.additions.length,2);for(const a of ap.additions){assert.equal(sha(a.expectedItem.a),a.afterSha256);const e=entries.get(a.entryId);assert.ok(e);let x=e.items.find(x=>x.id===a.questionId);if(!x){assert.equal(mode,'candidate',`final dist lacks approved append ${a.questionId}`);assert.equal(e.items.length,a.expectedOldCount);e.items.push(structuredClone(a.expectedItem));const count=typeof e.number==='string'&&/^(\s*)\d+(\s*问\s*)$/.exec(e.number);if(count)e.number=count[1]+e.items.length+count[2];stagedAppends++;x=e.items.at(-1);}assert.equal(e.items.indexOf(x),a.expectedIndex);assert.deepEqual(x,a.expectedItem);assert.equal(e.items.length,a.expectedOldCount+1);}return {stagedInMemory:stagedAppends,expectedAppends:2,alreadyApplied:ap.additions.length-stagedAppends};});
check('old-identity-prefix-is-unchanged',()=>{let count=0;for(const b of identity.entries){const e=entries.get(b.entryId);assert.ok(e);const add=ap.additions.filter(x=>x.entryId===b.entryId).length;assert.equal(e.items.length,b.oldCount+add);const countMatch=typeof b.numberBefore==='string'&&/^(\s*)\d+(\s*问\s*)$/.exec(b.numberBefore);const numberExpected=countMatch?countMatch[1]+(b.oldCount+add)+countMatch[2]:b.numberBefore;assert.equal(e.number,numberExpected);assert.deepEqual(Object.fromEntries(Object.entries(e).filter(([k])=>!['items','number'].includes(k))),b.entryFields);for(let i=0;i<b.oldCount;i++){assert.deepEqual(Object.fromEntries(Object.entries(e.items[i]).filter(([k])=>!['a','lead'].includes(k))),b.identities[i]);count++;}}return {oldQuestionsChecked:count};});
check('agent5-only-owned-six-block-span-changed',()=>{const s=mode==='final'?migration.workflowRecord.before:target('ai-agent-5#3').a;assert.equal(s,identity.agent5Prefix+identity.agent5SectionAfter+identity.agent5Suffix);if(mode==='final'){assert.equal(s,pkg.records.find(r=>r.entryId==='ai-agent-5').after);assert.equal(target('ai-agent-5#3').a,eighthLeaf('ai-agent-5',['items',3,'a'],migration.expectedFinalBody));assert.ok(migrationSummary);}const old=pkg.records.find(r=>r.entryId==='ai-agent-5').before;assert.equal(old,identity.agent5Prefix+identity.agent5SectionBefore+identity.agent5Suffix);assert.equal(semanticBlocks(identity.agent5SectionBefore).length,6);const beforeVariants=old.match(/<details class="qa-variants">[\s\S]*?<\/details>/g)||[];for(const x of beforeVariants)assert.ok(s.includes(x));return {changedSourceBlocks:6,otherBytesPreserved:true,bytePreservationLayer:'original service change before subsequent reviewed workflow migration',laterWorkflowMigrationVerified:mode==='final',migrationSummary};});
check('all322-old-semantic-blocks-have-exact-destinations',()=>{assert.equal(pm.recordFileSha256,sha(rt));let n=0;for(const map of pm.maps){const r=pkg.records.find(r=>r.entryId+'#'+r.path[1]===map.stableReviewKey&&r.path[2]==='a');assert.ok(r);assert.equal(map.beforeSha256,sha(r.before));const bs=semanticBlocks(r.before);assert.equal(bs.length,map.sourceBlockCount);assert.equal(bs.length,map.blocks.length);for(const [i,b] of map.blocks.entries()){assert.equal(b.sourceBlockIndex,i);assert.equal(bs[i][0],b.sourceHtml);assert.equal(sha(b.sourceHtml),b.sourceSha256);assert.equal(Array.from(r.before).slice(...b.sourceSpanCodePoints).join(''),b.sourceHtml);assert.ok(b.destinations.length);for(const [di,d] of b.destinations.entries()){assert.equal(sha(d.html),d.sha256);if(mode==='final')assertRelocatedDestination(migration,map.stableReviewKey,i,di,d,target);else assert.ok(target(d.stableReviewKey).a.includes(d.html),`missing exact destination ${d.stableReviewKey} for ${map.stableReviewKey} block ${i}`);}n++;}}assert.equal(n,322);assert.equal(n,pm.sourceCount);return {mappedBlocks:n};});
check('all20-variants-plus-inline-duplex-are-mapped',()=>{assert.equal(vm.originalVariantCount,20);assert.equal(vm.variants.length,20);const r=pkg.records.find(r=>r.entryId==='ai-模型与评测-8'&&r.path[2]==='a');const b=semanticBlocks(r.before);for(const [i,v] of vm.variants.entries()){assert.equal(v.sourceIndex,i);assert.equal(v.sourceBlockIndex,51+i);assert.equal(b[v.sourceBlockIndex][0],v.originalHtml);assert.ok(v.destinations.length);for(const d of v.destinations)assert.ok(target(d.stableReviewKey).a.includes(d.html));}const s=target('ai-模型与评测-8#1').a;const panel=s.match(/<details class="qa-variants"><summary>其他问法（(\d+)）<\/summary><ul class="md-list">([\s\S]*?)<\/ul><\/details>/);assert.ok(panel);assert.equal(Number(panel[1]),14);assert.equal([...panel[2].matchAll(/<li>/g)].length,14);assert.ok(!panel[2].includes('MySQL'));assert.ok(!panel[2].includes('Protobuf'));assert.ok(target('ai-agent-7#q-agent-runtime-duplex-contract').a.includes(vm.firstInlineVariant.original));return {oldVariants:20,remainingEquivalentVariants:14};});
check('html-anchors-and-all-internal-routes-resolve',()=>{const values=[...pkg.records.map(r=>r.after),...ap.additions.map(x=>x.expectedItem.a)];let routes=0;for(const s of values){balanced(s);assert.ok(!/<(?:pre|script|iframe|style)\b/i.test(s));for(const m of s.matchAll(/href="#\/e\/([^"/]+)(?:\/([^"/]+))?"/g)){const id=decodeURIComponent(m[1]),e=entries.get(id);assert.ok(e,`missing linked entry ${id}`);if(m[2]){const q=decodeURIComponent(m[2]);assert.ok(e.items?.some((x,i)=>(x.id||String(i))===q),`missing linked question ${id}#${q}`);}routes++;}}for(const r of pkg.records)for(const m of r.before.matchAll(/\bid="([^"]+)"/g))assert.ok(r.after.includes(`id="${m[1]}"`),`lost anchor ${m[1]}`);return {resolvedRoutes:routes};});
check('core-boundaries-and-no-new-compatibility-duplicate',()=>{const d=target('ai-agent-7#q-agent-runtime-duplex-contract').a,s=target('ai-模型与评测-3#q-model-public-inference-service').a,m=target('ai-模型与评测-8#1').a;for(const term of ['RECEIVED','PERSISTED','BUSINESS_COMMITTED','FINAL','同一事务边界','UNKNOWN','最大连续','缺口','leaseEpoch','operationId','SendMsg','RecvMsg','副作用提交本身','半关闭','Java 回调'])assert.ok(d.includes(term),term);for(const term of ['预处理','非有限数','只读加载','最大等待','不可变版本','计费','获准反馈','加载失败','并发热更'])assert.ok(s.includes(term),term);assert.ok(m.startsWith('<p class="md-p">我会按交互方式'));assert.ok(m.indexOf('HTTP/JSON')<m.indexOf('MySQL'));assert.equal(ap.additions.filter(x=>x.questionId.includes('protobuf')).length,0);for(const a of ap.additions){assert.ok(!/href="https?:\/\//.test(a.expectedItem.a),'public external reference links are not allowed');assert.ok(!a.expectedItem.a.includes('没有实验就说明'));}assert.ok(s.includes('最终结论用同一负载下实际测得的质量、容量和成本说明'));return {boundaries:'preserved',newProtobufDuplicates:0,publicExternalReferences:0};});
check('illustrative-durable-ack-does-not-skip-gaps',()=>{const stored=new Set(),applied=new Set();let watermark=0;function persist(n){stored.add(n);}function apply(n){assert.ok(stored.has(n));applied.add(n);while(stored.has(watermark+1)&&applied.has(watermark+1))watermark++;return watermark;}persist(1);persist(3);apply(3);assert.equal(watermark,0);apply(1);assert.equal(watermark,1);persist(2);apply(2);assert.equal(watermark,3);apply(3);assert.equal(watermark,3);assert.throws(()=>apply(4));return {fixture:'local state example only; no RPC/DB executed'};});
check('illustrative-local-commit-and-external-unknown',()=>{const ledger=new Map();let effects=0;function localCommit(id,payload){if(ledger.has(id)){assert.equal(ledger.get(id).payload,payload);return ledger.get(id);}const receipt={payload,state:'BUSINESS_COMMITTED'};effects++;ledger.set(id,receipt);return receipt;}const first=localCommit('op1','x');const afterLostAck=localCommit('op1','x');assert.equal(first,afterLostAck);assert.equal(effects,1);assert.throws(()=>localCommit('op1','different'));const remote={state:'UNKNOWN',operationId:'op2',attempt:1};function reconnect(x){return {...x,attempt:x.attempt+1};}assert.equal(reconnect(remote).operationId,'op2');assert.equal(reconnect(remote).state,'UNKNOWN');assert.notEqual(remote.state,'FAILED');return {fixture:'single-process atomic transition assumption; no distributed transaction claimed'};});
check('illustrative-generation-and-side-effect-order',()=>{let epoch=2,next=1;const computed=new Set([2,1]),commits=[];function commit(seq,e){if(e!==epoch||seq!==next||!computed.has(seq))return false;commits.push(seq);next++;return true;}assert.equal(commit(1,1),false);assert.equal(commit(2,2),false);assert.equal(commit(1,2),true);assert.equal(commit(2,2),true);assert.deepEqual(commits,[1,2]);const bounded={maxBytes:10,maxItems:2,bytes:0,items:0};function admit(n){if(n>bounded.maxBytes||bounded.bytes+n>bounded.maxBytes||bounded.items+1>bounded.maxItems)return false;bounded.bytes+=n;bounded.items++;return true;}assert.equal(admit(6),true);assert.equal(admit(5),false);assert.equal(admit(4),true);assert.equal(admit(0),false);return {fixture:'logical admission/ordering contract only'};});
const result={mode,dist,recordsSha256:sha(rt),verifierSha256:sha(fs.readFileSync(fileURLToPath(import.meta.url),'utf8')),actualFinalDistAcceptance:mode==='final'&&checks.every(x=>x.status==='passed'),siteWrites:0,passed:checks.filter(x=>x.status==='passed').length,failed:checks.filter(x=>x.status==='failed').length,total:checks.length,checks};console.log(JSON.stringify(result,null,2));if(checks.some(x=>x.status==='failed'))process.exitCode=1;
